  internal static R24KestrelAssets Acquire(){if(shared==null){var go=new GameObject("Shared authored Kestrel mesh/material/texture bank");shared=go.AddComponent<R24KestrelAssets>();shared.owners=1;shared.StartCoroutine(shared.Guard(shared.Load()));}else shared.owners++;return shared;}
  internal void Release(){if(disposed)return;if(--owners<=0){if(shared==this)shared=null;DisposeResources();Destroy(gameObject);}}
  IEnumerator Read(string name,Action<byte[]> accept){string url=Application.streamingAssetsPath+"/PlayableR23/Bots/"+name;if(!url.Contains("://"))url=new Uri(url).AbsoluteUri;using(var request=UnityWebRequest.Get(url)){pending=request;try{yield return request.SendWebRequest();if(request.result!=UnityWebRequest.Result.Success)throw new IOException("Kestrel "+name+": "+request.error);accept(request.downloadHandler.data);}finally{if(pending==request)pending=null;}}}
  IEnumerator Guard(IEnumerator work){var stack=new Stack<IEnumerator>();stack.Push(work);try{while(stack.Count>0){object value;try{var top=stack.Peek();if(!top.MoveNext()){var d=stack.Pop()as IDisposable;if(d!=null)d.Dispose();continue;}value=top.Current;}catch(Exception e){Failure=e.ToString();yield break;}var nested=value as IEnumerator;if(nested!=null)stack.Push(nested);else yield return value;}Ready=true;}finally{while(stack.Count>0){var d=stack.Pop()as IDisposable;if(d!=null)d.Dispose();}}}
  IEnumerator Load()
  {
   byte[] bytes=null;yield return Read("kestrel-soldier.json",b=>bytes=b);Skeleton=JsonUtility.FromJson<Data>(System.Text.Encoding.UTF8.GetString(bytes));if(Skeleton.version!=1||Skeleton.bones==null||Skeleton.bones.Length!=64)throw new IOException("Authored Kestrel skeleton format");
   var shader=Resources.Load<Shader>("R24KestrelSkin");if(shader==null)throw new InvalidOperationException("Authored Kestrel PBR shader missing");Skin=Own(new Material(shader));Skin.name="FederalSoldierSkin source PBR";
   foreach(string suffix in new[]{"Albedo","NormalMap","Occlusion","Roughness","Emission"}){yield return Read("kestrel-"+suffix+".png",b=>bytes=b);bool linear=suffix!="Albedo"&&suffix!="Emission";var texture=Own(new Texture2D(2,2,TextureFormat.RGBA32,false,linear));texture.name="Shared Kestrel "+suffix+(linear?" [linear]":" [sRGB]");if(!texture.LoadImage(bytes,true))throw new IOException("Kestrel image "+suffix);texture.filterMode=FilterMode.Trilinear;texture.wrapMode=TextureWrapMode.Repeat;texture.anisoLevel=4;Skin.SetTexture("_"+suffix,texture);}
   Dark=Lit(new Color(.035f,.045f,.05f),.55f,.38f);Edge=Lit(new Color(.48f,.53f,.5f),.8f,.38f);Gun=Lit(new Color(.12f,.15f,.16f),.8f,.48f);Threat=Lit(new Color(.18f,.85f,1),.25f,.38f);Threat.EnableKeyword("_EMISSION");Threat.SetColor("_EmissionColor",ShaderColor(new Color(.18f,.85f,1)*2.5f));Flash=Lit(new Color(1,.65f,.18f),0,.8f);Flash.EnableKeyword("_EMISSION");Flash.SetColor("_EmissionColor",ShaderColor(new Color(1,.65f,.18f)*5));
   Box=Own(R24KestrelGeometry.Box());Cylinder=Own(R24KestrelGeometry.Cylinder10());
   yield return Read("kestrel-soldier.skinbin",b=>bytes=b);using(var r=new BinaryReader(new MemoryStream(bytes))){if(r.ReadInt32()!=0x4b535631||r.ReadInt32()!=64)throw new IOException("Authored Kestrel skin header");int count=r.ReadInt32();if(count!=3)throw new IOException("Authored visible part count");for(int part=0;part<count;part++){string name=System.Text.Encoding.UTF8.GetString(r.ReadBytes(r.ReadInt32()));int nv=r.ReadInt32(),ni=r.ReadInt32(),influences=r.ReadInt32();if(nv<1||nv>10000||ni<3||ni>50000||influences!=8)throw new IOException("Kestrel source part bounds");var v=new Vector3[nv];var n=new Vector3[nv];var t=new Vector4[nv];var uv=new Vector2[nv];for(int i=0;i<nv;i++){v[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());n[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());t[i]=new Vector4(r.ReadSingle(),r.ReadSingle(),r.ReadSingle(),r.ReadSingle());uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());}var indices=new int[ni];for(int i=0;i<ni;i++)indices[i]=r.ReadInt32();R24KestrelGeometry.CorrectSourceWinding(indices);var joints=new int[nv*8];for(int i=0;i<joints.Length;i++)joints[i]=r.ReadInt32();var weights=new float[nv*8];for(int i=0;i<weights.Length;i++)weights[i]=r.ReadSingle();var bind=new Matrix4x4[64];for(int i=0;i<64;i++)for(int row=0;row<4;row++)for(int col=0;col<4;col++)bind[i][row,col]=r.ReadSingle();var mesh=Own(new Mesh());mesh.name="Shared authored Kestrel "+name;mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.vertices=v;mesh.normals=n;mesh.tangents=t;mesh.uv=uv;mesh.triangles=indices;mesh.bindposes=bind;
    var counts=new byte[nv];var list=new List<BoneWeight1>();for(int i=0;i<nv;i++){var row=new List<BoneWeight1>();float sum=0;for(int k=0;k<8;k++)if(weights[i*8+k]>0){row.Add(new BoneWeight1{boneIndex=joints[i*8+k],weight=weights[i*8+k]});sum+=weights[i*8+k];}if(row.Count==0)throw new IOException("Unweighted authored vertex");row.Sort((a,b)=>b.weight.CompareTo(a.weight));counts[i]=(byte)row.Count;foreach(var item in row)list.Add(new BoneWeight1{boneIndex=item.boneIndex,weight=item.weight/sum});}using(var nativeCount=new NativeArray<byte>(counts,Allocator.Temp))using(var nativeWeight=new NativeArray<BoneWeight1>(list.ToArray(),Allocator.Temp))mesh.SetBoneWeights(nativeCount,nativeWeight);mesh.RecalculateBounds();Parts.Add(new Part{Name=name,Mesh=mesh});}if(r.BaseStream.Position!=r.BaseStream.Length)throw new IOException("Kestrel trailing mesh bytes");}
   Original=R24EnemySourceGeometry.Acquire();ScoutMaterials=new[]{Lit(new Color(.19f,.24f,.25f),.75f,.38f),Edge,Dark,Lit(new Color(.9f,.52f,.08f),.35f,.38f),Threat,HexLit("263c40"),HexLit("809392"),HexLit("101b20"),HexLit("8e602b")};
   foreach(var group in Original.ForVariant(1).Groups){if(group.Parent>1)throw new IOException("Original Scout parent");Scout.Add(new ScoutPart{Mesh=group.Mesh,Original=group,Source=new ScoutRow{material=group.Material,turret=group.Parent==1,shadows=group.Shadows!=0,range=group.End,margin=group.Margin}});}

  }
  T Own<T>(T value)where T:UnityEngine.Object{resources.Add(value);return value;}
  internal static Color ShaderColor(Color source){bool gamma=QualitySettings.activeColorSpace==ColorSpace.Gamma;return new Color(Rgb(source.r,gamma),Rgb(source.g,gamma),Rgb(source.b,gamma),source.a);}
  static float Rgb(float v,bool gamma){return !gamma?v:v<=.0031308f?v*12.92f:(float)(1.055*Math.Pow(v,1/2.4)-.055);}
  Material HexLit(string hex){Color c;if(!ColorUtility.TryParseHtmlString("#"+hex,out c))throw new InvalidOperationException(hex);return Lit(c,.65f,.62f);}
  Material Lit(Color source,float metal,float rough){var shader=Shader.Find("Universal Render Pipeline/Lit");if(shader==null)throw new InvalidOperationException("Installed URP Lit missing");var m=Own(new Material(shader));m.SetColor("_BaseColor",ShaderColor(source));m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",1-rough);return m;}
  void DisposeResources(){if(disposed)return;disposed=true;StopAllCoroutines();if(pending!=null){pending.Abort();pending.Dispose();pending=null;}foreach(var item in resources)if(item!=null)Destroy(item);resources.Clear();Parts.Clear();Scout.Clear();if(Original!=null){Original.Release();Original=null;}}
  void OnDestroy(){if(shared==this)shared=null;DisposeResources();}
