 internal static class R24KestrelGeometry
 {
  // Packed source buffers face away from their authored normals after conversion.
  // Correct only render index order; keep every source attribute and triangle.
  internal static void CorrectSourceWinding(int[] indices){if(indices==null||indices.Length%3!=0)throw new IOException("Source triangle index count");for(int i=0;i<indices.Length;i+=3){int swap=indices[i+1];indices[i+1]=indices[i+2];indices[i+2]=swap;}}
  internal static Mesh Box(){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);var mesh=UnityEngine.Object.Instantiate(go.GetComponent<MeshFilter>().sharedMesh);go.SetActive(false);UnityEngine.Object.Destroy(go);mesh.name="Shared source BoxMesh geometry";return mesh;}
  internal static Mesh Cylinder10(){var v=new List<Vector3>();var n=new List<Vector3>();var uv=new List<Vector2>();var ix=new List<int>();for(int ring=0;ring<6;ring++)for(int j=0;j<=10;j++){float a=j*Mathf.PI*2/10;v.Add(new Vector3(Mathf.Cos(a),.5f-ring*.2f,Mathf.Sin(a)));n.Add(new Vector3(Mathf.Cos(a),0,Mathf.Sin(a)));uv.Add(new Vector2(j/10f,ring*.2f));}for(int ring=0;ring<5;ring++)for(int j=0;j<10;j++){int a=ring*11+j,b=a+11;ix.AddRange(new[]{a,a+1,b,a+1,b+1,b});}for(int side=0;side<2;side++){float y=side==0?.5f:-.5f;int c=v.Count;v.Add(new Vector3(0,y,0));n.Add(side==0?Vector3.up:Vector3.down);uv.Add(Vector2.one*.5f);for(int j=0;j<=10;j++){float a=j*Mathf.PI*2/10;v.Add(new Vector3(Mathf.Cos(a),y,Mathf.Sin(a)));n.Add(side==0?Vector3.up:Vector3.down);uv.Add(new Vector2(Mathf.Cos(a),Mathf.Sin(a))*.5f+Vector2.one*.5f);}for(int j=0;j<10;j++)ix.AddRange(side==0?new[]{c,c+j+2,c+j+1}:new[]{c,c+j+1,c+j+2});}var mesh=new Mesh();mesh.name="Shared source CylinderMesh radial10/rings4";mesh.SetVertices(v);mesh.SetNormals(n);mesh.SetUVs(0,uv);mesh.SetTriangles(ix,0);mesh.RecalculateTangents();return mesh;}
